import json, re

def set_nested_path(target, keys, val):
    curr = target
    for i, key in enumerate(keys[:-1]):
        next_key = keys[i+1]
        is_next_int = isinstance(next_key, int)

        if isinstance(curr, dict):
            if key not in curr:
                curr[key] = [] if is_next_int else {}
            curr = curr[key]
        elif isinstance(curr, list):
            while len(curr) <= key:
                curr.append(None)
            if curr[key] is None:
                curr[key] = [] if is_next_int else {}
            curr = curr[key]

    key = keys[-1]
    if isinstance(curr, dict):
        curr[key] = val
    elif isinstance(curr, list):
        while len(curr) <= key:
            curr.append(None)
        curr[key] = val

def parse_key_path(key_str):
    # Parse e.g. a[b][0][c]
    m = re.match(r'^([^\[\]]+)(.*)$', key_str)
    if not m:
        return [key_str]
    root = m.group(1)
    rest = m.group(2)
    keys = [root]
    for sub in re.findall(r'\[([^\[\]]*)\]', rest):
        if sub.isdigit():
            keys.append(int(sub))
        else:
            keys.append(sub)
    return keys

res = {}
for path, val in [('a[b][0]', 'x'), ('a[b][1]', 'y'), ('a[c]', 123)]:
    keys = parse_key_path(path)
    set_nested_path(res, keys, val)

print(json.dumps(res))
""}

