import re

def colorize_json_auto(s):
    # Tokens: strings, numbers, booleans/null, structural
    token_pattern = re.compile(
        r'(\"(?:\\.|[^\"\\])*\")|'                  # 1: String
        r'(-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)|'     # 2: Number
        r'\b(true|false|null)\b|'                  # 3: Boolean/Null
        r'([\{\}\[\]:,])|'                         # 4: Punctuation
        r'(\s+)'                                   # 5: Whitespace
    )

    # We need to distinguish between object keys and string values.
    # In JSON, a key string is followed by optional whitespace and ':'
    tokens = []
    pos = 0
    while pos < len(s):
        m = token_pattern.search(s, pos)
        if not m:
            tokens.append(s[pos:])
            break
        if m.start() > pos:
            tokens.append(s[pos:m.start()])

        string, number, boolean_null, punct, ws = m.groups()
        if string:
            # Check if this string is a key (followed by optional ws and ':')
            lookahead = s[m.end():]
            if re.match(r'^\s*:', lookahead):
                # Key
                tokens.append('\x1b[0m\x1b[38;5;12m' + string + '\x1b[0m')
            else:
                # String value
                tokens.append('\x1b[0m\x1b[33m' + string + '\x1b[0m')
        elif number:
            tokens.append('\x1b[0m\x1b[34m' + number + '\x1b[0m')
        elif boolean_null:
            tokens.append('\x1b[0m\x1b[33m' + boolean_null + '\x1b[0m')
        elif punct:
            tokens.append('\x1b[0m' + punct)
        elif ws:
            tokens.append('\x1b[0m' + ws)

        pos = m.end()
    return ''.join(tokens)

s = '{\n    \"foo\": \"bar\",\n    \"count\": 123,\n    \"ok\": true\n}'
print(repr(colorize_json_auto(s)))
""}

