        try:
            val = json.loads(val_str)
        except Exception as e:
            return {"type": "error", "msg": str(e)}
        return {"type": "json_field", "key": key, "value": val}
    elif sep == "=":
        val = read_file_or_val(raw_val)
        return {"type": "json_field" if True else "form_field", "key": key, "value": val}
    elif sep == "@":
        # File field upload
        # raw_val can contain ;type= and ;filename=
        parts = raw_val.split(";")
        filepath = parts[0]
        filename = os.path.basename(filepath)
        mime = None
        for p in parts[1:]:
            if p.startswith("type="):
                mime = p[5:]
            elif p.startswith("filename="):
                filename = p[9:]
        if not os.path.exists(filepath):
            return {"type": "error", "msg": f"file '{filepath}' not found"}
        with open(filepath, "rb") as f:
            content = f.read()
        if not mime:
            mime, _ = mimetypes.guess_type(filepath)
        return {"type": "file_field", "key": key, "value": {"filename": filename, "content": content, "mime": mime or "application/octet-stream"}}
    elif sep == ":":
        if raw_val == "":
            return {"type": "unset_header", "key": key}
        else:
            if raw_val.startswith("@"):
                val = read_file_or_val(raw_val).rstrip("\r\n")
            else:
                val = unescape_str(raw_val)
            return {"type": "header", "key": key, "value": val}
    elif sep == ";":
        return {"type": "empty_header", "key": key}


def unescape_str(s):
    res = []
    escaped = False
    for c in s:
        if escaped:
            res.append(c)
            escaped = False
        elif c == '\\':
            escaped = True
        else:
            res.append(c)
    return "".join(res)


def read_file_or_val(s):
    if s.startswith("@"):
        filepath = s[1:]
        with open(filepath, "r", encoding="utf-8", errors="replace") as f:
            return f.read()
    return unescape_str(s)


def parse_key_path(key_str):
    m = re.match(r'^([^\[\]]+)(.*)$', key_str)
    if not m:
        return [key_str]
    root = m.group(1)
    rest = m.group(2)
    keys = [root]
    for sub in re.findall(r'\[([^\[\]]*)\]', rest):
        if sub.isdigit():
            keys.append(int(sub))
        else:
            keys.append(sub)
    return keys


def set_nested_path(target, keys, val):
    curr = target
    for i, key in enumerate(keys[:-1]):
        next_key = keys[i+1]
        is_next_int = isinstance(next_key, int)
        if isinstance(curr, dict):
            if key not in curr:
                curr[key] = [] if is_next_int else {}
            curr = curr[key]
        elif isinstance(curr, list):
            while len(curr) <= key:
                curr.append(None)
            if curr[key] is None:
                curr[key] = [] if is_next_int else {}
            curr = curr[key]

    key = keys[-1]
    if isinstance(curr, dict):
        curr[key] = val
    elif isinstance(curr, list):
        while len(curr) <= key:
            curr.append(None)
        curr[key] = val


def encode_multipart(form_data, multipart_data, boundary):
    lines = []
    for k, v in form_data:
        lines.append(f"--{boundary}".encode("utf-8"))
        lines.append(f'Content-Disposition: form-data; name="{k}"'.encode("utf-8"))
        lines.append(b"")
        lines.append(v.encode("utf-8") if isinstance(v, str) else v)
    for k, v in multipart_data:
        lines.append(f"--{boundary}".encode("utf-8"))
        lines.append(f'Content-Disposition: form-data; name="{k}"; filename="{v["filename"]}"'.encode("utf-8"))
        lines.append(f'Content-Type: {v["mime"]}'.encode("utf-8"))
        lines.append(b"")
        lines.append(v["content"])
    lines.append(f"--{boundary}--".encode("utf-8"))
    lines.append(b"")
    return b"\r\n".join(lines)


def run_curl_translation(bin_name, method, full_url, headers, unset_headers, json_data, form_data, multipart_data, raw_body, stdin_body, opts):
    curl_bin = "curl"
    args = []
    env_prefix = ""

    long_mode = opts["curl_long"]

    if opts["proxy"]:
        # Extract proxy
        for p in opts["proxy"]:
            if p.startswith("http:"):
                env_prefix = f"http_proxy={p[5:]} "
            elif p.startswith("https:"):
                env_prefix = f"https_proxy={p[6:]} "

    if method == "HEAD":
        args.append("--head" if long_mode else "-I")
    elif method != "GET" or json_data or form_data or multipart_data or raw_body:
        if method != "GET":
            args.append(f"--request {method}" if long_mode else f"-X {method}")

    args.append(f"'{full_url}'" if "?" in full_url or "&" in full_url else full_url)

    if not opts["verify"]:
        args.append("--insecure" if long_mode else "-k")
    if opts["follow"]:
        args.append("--location" if long_mode else "-L")
    if opts["timeout"]:
        args.append(f"--max-time {int(opts['timeout'])}")
    if opts["ipv4"]:
        args.append("--ipv4" if long_mode else "-4")
    if opts["ipv6"]:
        args.append("--ipv6" if long_mode else "-6")

    # Auth
    if opts["bearer"]:
        args.append(f"--oauth2-bearer {opts['bearer']}")
    elif opts["auth"]:
        if opts["auth_type"] == "bearer":
            args.append(f"--oauth2-bearer {opts['auth']}")
        elif opts["auth_type"] == "basic":
            args.append(f"--basic {'--user' if long_mode else '-u'} {opts['auth']}")

    # Headers
    h_opt = "--header" if long_mode else "-H"
    for h_lower, (h_orig, h_val) in headers.items():
        args.append(f"{h_opt} '{h_orig.lower()}: {h_val}'")
    for u in unset_headers:
        args.append(f"{h_opt} {u}:")

    # Data
    if json_data:
        args.append(f"{h_opt} 'content-type: application/json'")
        args.append(f"{h_opt} 'accept: application/json, */*;q=0.5'")
        data_str = json.dumps(json_data, separators=(',', ':'))
        args.append(f"{'--data' if long_mode else '-d'} '{data_str}'")
    elif form_data:
        for k, v in form_data:
            args.append(f"--data-urlencode '{k}={v}'")
    elif multipart_data:
        for k, v in multipart_data:
            args.append(f"{'--form' if long_mode else '-F'} '{k}={v['filename']}'")

    print(f"{env_prefix}{curl_bin} " + " ".join(args))


def print_offline_request(method, path, query, req_headers, body_bytes, opts):
    full_path = path + ("?" + query if query else "")
    lines = [f"{method} {full_path} HTTP/1.1"]

    # Sort headers
    sorted_headers = sorted(req_headers.items(), key=lambda x: x[0].lower())
    for k, v in sorted_headers:
        lines.append(f"{k}: {v}")

    req_str = "\n".join(lines) + "\n\n"
    if body_bytes:
        req_str += body_bytes.decode("utf-8", errors="replace") + "\n\n"

    # Check print mode for offline
    p = opts["print"]
    if p is None:
        p = "HB"

    out = ""
    if "H" in p:
        out += "\n".join(lines) + "\n\n"
    if "B" in p and body_bytes:
        out += body_bytes.decode("utf-8", errors="replace") + "\n\n"

    sys.stdout.write(out)


def execute_request(scheme, netloc, path, query, method, req_headers, body_bytes, opts):
    full_path = path + ("?" + query if query else "")

    # Parse host/port
    host = netloc
    port = 443 if scheme == "https" else 80
    if ":" in netloc:
        parts = netloc.split(":", 1)
        host = parts[0]
        port = int(parts[1])

    start_time = time.time()

    conn = None
    try:
        if scheme == "https":
            context = ssl.create_default_context()
            if not opts["verify"]:
                context.check_hostname = False
                context.verify_mode = ssl.CERT_NONE
            conn = http.client.HTTPSConnection(host, port, timeout=opts["timeout"], context=context)
        else:
            conn = http.client.HTTPConnection(host, port, timeout=opts["timeout"])

        conn.request(method, full_path, body=body_bytes if body_bytes else None, headers=req_headers)
        res = conn.getresponse()
        elapsed = time.time() - start_time

        res_body = res.read()

        # Decompress if needed
        encoding = res.headers.get("Content-Encoding", "")
        if "gzip" in encoding:
            try: res_body = gzip.decompress(res_body)
            except Exception: pass
        elif "deflate" in encoding:
            try: res_body = zlib.decompress(res_body)
            except Exception: pass

        # Determine print format
        is_tty = sys.stdout.isatty()
        p = opts["print"]
        if p is None:
            if opts["verbose"] >= 2: p = "HhBbm"
            elif opts["verbose"] >= 1: p = "HhBb"
            elif is_tty: p = "hb"
            else: p = "b"

        # Determine pretty format
        pretty = opts["pretty"]
        if pretty is None:
            if os.environ.get("NO_COLOR") is not None: pretty = "format"
            elif is_tty: pretty = "all"
            else: pretty = "none"

        output_str = ""

        # Request headers / body
        if "H" in p:
            req_lines = [f"{method} {full_path} HTTP/1.1"]
            for k, v in req_headers.items():
                req_lines.append(f"{k}: {v}")
            output_str += "\n".join(req_lines) + "\n\n"

        if "B" in p and body_bytes:
            output_str += body_bytes.decode("utf-8", errors="replace") + "\n\n"

        # Response headers / body
        if "h" in p:
            res_lines = [f"HTTP/1.1 {res.status} {res.reason}"]
            res_hdrs = list(res.headers.items())
            if opts["format_options"].get("headers.sort", True):
                res_hdrs = sorted(res_hdrs, key=lambda x: x[0].lower())
            for k, v in res_hdrs:
                res_lines.append(f"{k}: {v}")
            output_str += "\n".join(res_lines) + "\n\n"

        if "b" in p and res_body:
            body_text = res_body.decode("utf-8", errors="replace")
            # Format JSON if requested
            if pretty in ["all", "format"] and opts["format_options"].get("json.format", True):
                try:
                    parsed_json = json.loads(body_text)
                    indent = opts["format_options"].get("json.indent", 4)
                    body_text = json.dumps(parsed_json, indent=indent)
                except Exception:
                    pass
            output_str += body_text + "\n\n"

        if "m" in p:
            output_str += f"Elapsed time: {elapsed:.5f}s\nRemote address: {host}:{port}\n\n"

        # Apply coloring if pretty in ["all", "colors"]
        if pretty in ["all", "colors"]:
            output_str = colorize_output(output_str, opts["style"])

        # Write output to stdout or file
        if opts["output"]:
            with open(opts["output"], "wb") as f:
                f.write(res_body)
        elif opts["download"]:
            if is_tty:
                # Save to file from Content-Disposition
                cd = res.headers.get("Content-Disposition", "")
                filename = "download"
                if "filename=" in cd:
                    filename = cd.split("filename=")[1].strip('"\'')
                with open(filename, "wb") as f:
                    f.write(res_body)
                print(f"Downloading to \"{filename}\"\nDone. {len(res_body)} B", file=sys.stderr)
            else:
                sys.stdout.buffer.write(res_body)
        else:
            sys.stdout.write(output_str)

        # Check status exit code
        if opts["check_status"]:
            if 400 <= res.status < 500:
                print(f"{bin_name}: warning: HTTP {res.status} {res.reason}", file=sys.stderr)
                sys.exit(4)
            elif 500 <= res.status < 600:
                print(f"{bin_name}: warning: HTTP {res.status} {res.reason}", file=sys.stderr)
                sys.exit(5)
            elif 300 <= res.status < 400 and not opts["follow"]:
                print(f"{bin_name}: warning: HTTP {res.status} {res.reason}", file=sys.stderr)
                sys.exit(3)

        sys.exit(0)

    except Exception as e:
        print(f"{bin_name}: error: {e}", file=sys.stderr)
        sys.exit(1)


def colorize_output(s, style):
    # Simple colorizer for headers + json
    return s


