                        opts["raw"] = val
                elif base_name == "format-options":
                    if is_no:
                        opts["format_options"] = {"json.indent": 4, "json.format": True, "headers.sort": True}
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        if val:
                            for item in val.split(","):
                                if ":" in item:
                                    k, v = item.split(":", 1)
                                    if k == "json.indent":
                                        opts["format_options"]["json.indent"] = int(v)
                                    elif k == "json.format":
                                        opts["format_options"]["json.format"] = (v.lower() == "true")
                                    elif k == "headers.sort":
                                        opts["format_options"]["headers.sort"] = (v.lower() == "true")
                elif base_name == "print":
                    if is_no:
                        opts["print"] = ""
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        opts["print"] = val if val else ""
                elif base_name == "verbose":
                    if is_no:
                        opts["verbose"] = 0
                    else:
                        opts["verbose"] = 1
                elif base_name == "auth-type":
                    if is_no:
                        opts["auth_type"] = "basic"
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        opts["auth_type"] = val
                elif base_name in ["auth", "a"]:
                    if is_no:
                        opts["auth"] = None
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        opts["auth"] = val
                elif base_name == "bearer":
                    if is_no:
                        opts["bearer"] = None
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        opts["bearer"] = val
                        opts["auth_type"] = "bearer"
                elif base_name == "output":
                    if is_no:
                        opts["output"] = None
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        opts["output"] = val
                elif base_name == "session":
                    if is_no:
                        opts["session"] = None
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        opts["session"] = val
                elif base_name == "session-read-only":
                    if is_no:
                        opts["session_read_only"] = None
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        opts["session_read_only"] = val
                elif base_name == "timeout":
                    if is_no:
                        opts["timeout"] = None
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        opts["timeout"] = float(val) if val else None
                elif base_name == "max-redirects":
                    if is_no:
                        opts["max_redirects"] = 30
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        opts["max_redirects"] = int(val) if val else 30
                elif base_name == "proxy":
                    if is_no:
                        opts["proxy"] = []
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        if val:
                            opts["proxy"].append(val)
                elif base_name == "verify":
                    if is_no:
                        opts["verify"] = False
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        if val in ["no", "false", "False"]:
                            opts["verify"] = False
                        elif val in ["yes", "true", "True"]:
                            opts["verify"] = True
                        else:
                            opts["verify"] = val
                elif base_name == "default-scheme":
                    if is_no:
                        opts["default_scheme"] = default_scheme
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        opts["default_scheme"] = val
                elif base_name == "unix-socket":
                    if is_no:
                        opts["unix_socket"] = None
                    else:
                        if val is None and i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        opts["unix_socket"] = val
                else:
                    print(f"error: unexpected argument '--{opt_name}' found\n\n  tip: to pass '--{opt_name}' as a value, use '-- --{opt_name}'\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
                    sys.exit(2)
                i += 1
                continue

            short_str = arg[1:]
            j = 0
            while j < len(short_str):
                ch = short_str[j]
                if ch == 'j': opts["json"] = True
                elif ch == 'f': opts["form"] = True
                elif ch == 'h': opts["print"] = "h" if opts["print"] is None else opts["print"] + "h"
                elif ch == 'b': opts["print"] = "b" if opts["print"] is None else opts["print"] + "b"
                elif ch == 'm': opts["print"] = "m" if opts["print"] is None else opts["print"] + "m"
                elif ch == 'v': opts["verbose"] += 1
                elif ch == 'q': opts["quiet"] = True
                elif ch == 'S': opts["stream"] = True
                elif ch == 'd': opts["download"] = True
                elif ch == 'c': opts["continue"] = True
                elif ch == 'F': opts["follow"] = True
                elif ch == '4': opts["ipv4"] = True
                elif ch == '6': opts["ipv6"] = True
                elif ch == 'I': opts["ignore_stdin"] = True
                elif ch in ['s', 'p', 'o', 'A', 'a']:
                    val = short_str[j+1:]
                    if not val:
                        if i + 1 < len(args_list):
                            val = args_list[i+1]
                            i += 1
                        else:
                            print(f"error: a value is required for '-{ch}' but none was supplied", file=sys.stderr)
                            sys.exit(2)
                    if ch == 's': opts["style"] = val
                    elif ch == 'p': opts["print"] = val
                    elif ch == 'o': opts["output"] = val
                    elif ch == 'A': opts["auth_type"] = val
                    elif ch == 'a': opts["auth"] = val
                    break
                else:
                    print(f"error: unexpected argument '-{ch}' found", file=sys.stderr)
                    sys.exit(2)
                j += 1
            i += 1
            continue

        positional.append(arg)
        i += 1

    if opts["short_version"]:
        print(f"xh {VERSION}")
        sys.exit(0)
    if opts["version"]:
        print(f"xh {VERSION}\n-native-tls +rustls")
        sys.exit(0)
    if opts["help"]:
        print_short_help(bin_name)
        sys.exit(0)
    if opts["long_help"]:
        print_long_help(bin_name)
        sys.exit(0)
    if opts["generate"]:
        generate_output(opts["generate"], bin_name)
        sys.exit(0)

    if not positional:
        print(f"error: the following required arguments were not provided:\n  <[METHOD] URL>\n\nUsage: {bin_name} <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
        sys.exit(2)

    method = None
    explicit_method = False
    url_str = None
    items_raw = []

    first_arg = positional[0]
    std_methods = {"GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS", "CONNECT", "TRACE"}

    if len(positional) >= 2:
        if first_arg.upper() in std_methods or (first_arg.isalpha() and not (":" in first_arg or "." in first_arg or "/" in first_arg)):
            method = first_arg.upper()
            explicit_method = True
            url_str = positional[1]
            items_raw = positional[2:]
        else:
            url_str = first_arg
            items_raw = positional[1:]
    else:
        url_str = first_arg
        items_raw = []

    scheme, netloc, path, query, fragment = parse_url(url_str, opts["default_scheme"], opts["https"])

    user_headers = []
    unset_headers = set()
    query_params = []
    json_data = {}
    form_data = []
    multipart_data = []
    has_file_fields = False
    raw_body = None

    for item in items_raw:
        parsed = parse_request_item(item)
        if parsed["type"] == "error":
            print(f"error: Invalid value for '[REQUEST_ITEM]...': \"{item}\" {parsed['msg']}\n\nUsage: {bin_name} [OPTIONS] <[METHOD] URL> [REQUEST_ITEM]...\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)

        t = parsed["type"]
        k = parsed.get("key")
        v = parsed.get("value")
        raw_v = parsed.get("raw_value")

        if t == "query":
            query_params.append((k, v))
        elif t == "header":
            user_headers.append((k, v, raw_v))
        elif t == "unset_header":
            unset_headers.add(k.lower())
        elif t == "empty_header":
            user_headers.append((k, "", ""))
        elif t == "json_field":
            set_nested_path(json_data, parse_key_path(k), v)
        elif t == "form_field":
            form_data.append((k, v))
        elif t == "file_field":
            has_file_fields = True
            multipart_data.append((k, v))
        elif t == "raw_body":
            raw_body = v

    stdin_body = None
    if not sys.stdin.isatty() and not opts["ignore_stdin"]:
        try:
            stdin_body = sys.stdin.buffer.read()
        except Exception:
            pass

    if stdin_body and len(stdin_body) > 0 and (json_data or form_data or multipart_data or raw_body):
        print(f"{bin_name}: error: Request body (from stdin) and request data (key=value) cannot be mixed. Pass --ignore-stdin to ignore standard input.", file=sys.stderr)
        sys.exit(1)

    has_body_data = bool(json_data or form_data or multipart_data or raw_body or (stdin_body is not None and len(stdin_body) > 0))
    if not method:
        method = "POST" if has_body_data else "GET"

    # Build final query string
    if query_params:
        encoded_q = urllib.parse.urlencode(query_params)
        query = (query + "&" + encoded_q) if query else encoded_q

    full_url = urllib.parse.urlunsplit((scheme, netloc, path, query, fragment))

    if opts["curl"] or opts["curl_long"]:
        run_curl_translation(bin_name, method, explicit_method, full_url, user_headers, unset_headers, json_data, form_data, multipart_data, raw_body, stdin_body, opts)
        sys.exit(0)

    # Construct request body & content-type
    body_bytes = b""
    content_type = None

    if raw_body is not None:
        body_bytes = raw_body["content"]
        content_type = raw_body["mime"]
    elif stdin_body is not None and len(stdin_body) > 0:
        body_bytes = stdin_body
        content_type = "application/json" if opts["json"] else "text/plain"
    elif json_data:
        body_bytes = json.dumps(json_data, separators=(',', ':')).encode('utf-8')
        content_type = "application/json"
    elif form_data or (has_file_fields or opts["multipart"]):
        if opts["multipart"] or has_file_fields:
            boundary = "936935871f8f7f96-f99da853b60f5ae4-b040cf45a4f196dd-108c300b08e0bc6e"
            content_type = f"multipart/form-data; boundary={boundary}"
            body_bytes = encode_multipart(form_data, multipart_data, boundary)
        else:
            content_type = "application/x-www-form-urlencoded"
            body_bytes = urllib.parse.urlencode(form_data).encode('utf-8')

    # Construct ordered request headers
    # Header order in xh:
    # 1. Accept-Encoding
    # 2. User-Agent
    # 3. Connection
    # 4. Accept
    # 5. Content-Type (if body)
    # 6. Auth / User headers
    # 7. Content-Length (if body)
    # 8. Host

    header_list = []

    # Check user overrides
    user_header_keys = {k.lower(): (k, v, rv) for k, v, rv in user_headers}

    if "accept-encoding" not in unset_headers and "accept-encoding" not in user_header_keys:
        header_list.append(("Accept-Encoding", "gzip, deflate, br, zstd"))

    if "user-agent" not in unset_headers and "user-agent" not in user_header_keys:
        header_list.append(("User-Agent", f"xh/{VERSION}"))

    if "connection" not in unset_headers and "connection" not in user_header_keys:
        header_list.append(("Connection", "keep-alive"))

    if "accept" not in unset_headers and "accept" not in user_header_keys:
        if content_type == "application/json" or (opts["json"] and not content_type):
            header_list.append(("Accept", "application/json, */*;q=0.5"))
        else:
            header_list.append(("Accept", "*/*"))

    if content_type and "content-type" not in unset_headers and "content-type" not in user_header_keys:
        header_list.append(("Content-Type", content_type))

    # Add Auth header if set
    if "authorization" not in unset_headers and "authorization" not in user_header_keys:
        if opts["bearer"]:
            header_list.append(("Authorization", f"Bearer {opts['bearer']}"))
        elif opts["auth"]:
            if opts["auth_type"] == "bearer":
                header_list.append(("Authorization", f"Bearer {opts['auth']}"))
            elif opts["auth_type"] == "basic":
                encoded = base64.b64encode(opts["auth"].encode("utf-8")).decode("utf-8")
                header_list.append(("Authorization", f"Basic {encoded}"))

    # Add user custom headers
    for k, v, rv in user_headers:
        if k.lower() not in unset_headers:
            header_val = f" {v}" if rv.startswith(" ") else v
            header_list.append((k, header_val))

    if (has_body_data or method == "POST") and "content-length" not in unset_headers and "content-length" not in user_header_keys:
        header_list.append(("Content-Length", str(len(body_bytes))))

    if "host" not in unset_headers and "host" not in user_header_keys:
        header_list.append(("Host", netloc))

    if opts["offline"]:
        print_offline_request(method, path, query, header_list, body_bytes, opts)
        sys.exit(0)

    execute_request(scheme, netloc, path, query, method, header_list, body_bytes, opts)


def parse_url(url_str, default_scheme, force_https):
    if url_str.startswith("://"):
        url_str = default_scheme + url_str
    elif url_str.startswith("//"):
        url_str = default_scheme + ":" + url_str
    elif not (url_str.startswith("http://") or url_str.startswith("https://")):
        if url_str.startswith(":"):
            rest = url_str[1:]
            if rest.startswith("/"):
                url_str = default_scheme + "://localhost" + rest
            elif ":" in rest or "/" in rest:
                url_str = default_scheme + "://localhost:" + rest
            elif rest.isdigit():
                url_str = default_scheme + "://localhost:" + rest
            else:
                url_str = default_scheme + "://localhost/" + rest
        else:
            url_str = default_scheme + "://" + url_str

    if force_https and url_str.startswith("http://"):
        url_str = "https://" + url_str[7:]

    parsed = urllib.parse.urlsplit(url_str)
    scheme = parsed.scheme if parsed.scheme else default_scheme
    netloc = parsed.netloc

    # Check credentials in URL
    if "@" in netloc and not parsed.username:
        pass

    path = parsed.path if parsed.path else "/"
    query = parsed.query
    fragment = parsed.fragment
    return scheme, netloc, path, query, fragment


def parse_request_item(item):
    escaped = False
    sep = None
    sep_idx = -1

    i = 0
    while i < len(item):
        c = item[i]
        if escaped:
            escaped = False
            i += 1
            continue
        if c == '\\':
            escaped = True
            i += 1
            continue

        if item[i:i+2] == "==":
            sep = "=="
            sep_idx = i
            break
        elif item[i:i+2] == ":=":
            sep = ":="
            sep_idx = i
            break
        elif c == '=':
            sep = "="
            sep_idx = i
            break
        elif c == '@' and i > 0:
            sep = "@"
            sep_idx = i
            break
        elif c == ':':
            sep = ":"
            sep_idx = i
            break
        elif c == ';':
            sep = ";"
            sep_idx = i
            break
        i += 1

    if item.startswith("@") and sep_idx != 0:
        filename = item[1:]
        if not os.path.exists(filename):
            return {"type": "error", "msg": f"file '{filename}' not found"}
        with open(filename, "rb") as f:
            content = f.read()
        mime, _ = mimetypes.guess_type(filename)
        return {"type": "raw_body", "value": {"content": content, "mime": mime or "text/plain"}}

    if sep is None:
        return {"type": "error", "msg": "expected separator"}

    raw_key = item[:sep_idx]
    raw_val = item[sep_idx + len(sep):]

    key = unescape_str(raw_key)

    if sep == "==":
        val = read_file_or_val(raw_val)
        return {"type": "query", "key": key, "value": val}
    elif sep == ":=":
        val_str = read_file_or_val(raw_val)
        try:
            val = json.loads(val_str)
        except Exception as e:
            return {"type": "error", "msg": str(e)}
        return {"type": "json_field", "key": key, "value": val}
    elif sep == "=":
        val = read_file_or_val(raw_val)
        return {"type": "json_field", "key": key, "value": val}
    elif sep == "@":
        parts = raw_val.split(";")
        filepath = parts[0]
        filename = os.path.basename(filepath)
        mime = None
        for p in parts[1:]:
            if p.startswith("type="):
                mime = p[5:]
            elif p.startswith("filename="):
                filename = p[9:]
        if not os.path.exists(filepath):
            return {"type": "error", "msg": f"file '{filepath}' not found"}
        with open(filepath, "rb") as f:
            content = f.read()
        if not mime:
            mime, _ = mimetypes.guess_type(filepath)
        return {"type": "file_field", "key": key, "value": {"filename": filename, "content": content, "mime": mime or "application/octet-stream"}}
    elif sep == ":":
        if raw_val == "":
            return {"type": "unset_header", "key": key}
        else:
            if raw_val.startswith("@"):
                val = read_file_or_val(raw_val).rstrip("\r\n")
            else:
                val = unescape_str(raw_val.lstrip() if raw_val.startswith(" ") else raw_val)
            return {"type": "header", "key": key, "value": val, "raw_value": raw_val}
    elif sep == ";":
        return {"type": "empty_header", "key": key}


def unescape_str(s):
    res = []
    escaped = False
    for c in s:
        if escaped:
            res.append(c)
            escaped = False
        elif c == '\\':
            escaped = True
        else:
            res.append(c)
    return "".join(res)


def read_file_or_val(s):
    if s.startswith("@"):
        filepath = s[1:]
        with open(filepath, "r", encoding="utf-8", errors="replace") as f:
            return f.read()
    return unescape_str(s)


def parse_key_path(key_str):
    m = re.match(r'^([^\[\]]+)(.*)$', key_str)
    if not m:
        return [key_str]
    root = m.group(1)
    rest = m.group(2)
    keys = [root]
    for sub in re.findall(r'\[([^\[\]]*)\]', rest):
        if sub.isdigit():
            keys.append(int(sub))
        else:
            keys.append(sub)
    return keys


def set_nested_path(target, keys, val):
    curr = target
    for i, key in enumerate(keys[:-1]):
        next_key = keys[i+1]
        is_next_int = isinstance(next_key, int)
        if isinstance(curr, dict):
            if key not in curr:
                curr[key] = [] if is_next_int else {}
            curr = curr[key]
        elif isinstance(curr, list):
            while len(curr) <= key:
                curr.append(None)
            if curr[key] is None:
                curr[key] = [] if is_next_int else {}
            curr = curr[key]

    key = keys[-1]
    if isinstance(curr, dict):
        curr[key] = val
    elif isinstance(curr, list):
        while len(curr) <= key:
            curr.append(None)
        curr[key] = val


def encode_multipart(form_data, multipart_data, boundary):
    lines = []
    for k, v in form_data:
        lines.append(f"--{boundary}".encode("utf-8"))
        lines.append(f'Content-Disposition: form-data; name="{k}"'.encode("utf-8"))
        lines.append(b"")
        lines.append(v.encode("utf-8") if isinstance(v, str) else v)
    for k, v in multipart_data:
        lines.append(f"--{boundary}".encode("utf-8"))
        lines.append(f'Content-Disposition: form-data; name="{k}"; filename="{v["filename"]}"'.encode("utf-8"))
        lines.append(f'Content-Type: {v["mime"]}'.encode("utf-8"))
        lines.append(b"")
        lines.append(v["content"])
    lines.append(f"--{boundary}--".encode("utf-8"))
    lines.append(b"")
    return b"\r\n".join(lines)


def run_curl_translation(bin_name, method, explicit_method, full_url, user_headers, unset_headers, json_data, form_data, multipart_data, raw_body, stdin_body, opts):
    curl_bin = "curl"
    args = []
    env_prefix = ""
    long_mode = opts["curl_long"]

    if opts["proxy"]:
        for p in opts["proxy"]:
            if p.startswith("http:"):
                env_prefix = f"http_proxy={p[5:]} "
            elif p.startswith("https:"):
                env_prefix = f"https_proxy={p[6:]} "

    if method == "HEAD":
        args.append("--head" if long_mode else "-I")
    elif explicit_method:
        args.append(f"--request {method}" if long_mode else f"-X {method}")

    args.append(f"'{full_url}'" if "?" in full_url or "&" in full_url else full_url)

    if not opts["verify"]:
        args.append("--insecure" if long_mode else "-k")
    if opts["follow"]:
        args.append("--location" if long_mode else "-L")
    if opts["timeout"]:
        args.append(f"--max-time {int(opts['timeout'])}")
    if opts["ipv4"]:
        args.append("--ipv4" if long_mode else "-4")
    if opts["ipv6"]:
        args.append("--ipv6" if long_mode else "-6")

    if opts["bearer"]:
        args.append(f"--oauth2-bearer {opts['bearer']}")
    elif opts["auth"]:
        if opts["auth_type"] == "bearer":
            args.append(f"--oauth2-bearer {opts['auth']}")
        elif opts["auth_type"] == "basic":
            args.append(f"--basic {'--user' if long_mode else '-u'} {opts['auth']}")

    h_opt = "--header" if long_mode else "-H"
    for k, v, rv in user_headers:
        if k.lower() not in unset_headers:
            args.append(f"{h_opt} '{k.lower()}: {v}'")

    for u in unset_headers:
        args.append(f"{h_opt} {u}:")

    if json_data:
        args.append(f"{h_opt} 'content-type: application/json'")
        args.append(f"{h_opt} 'accept: application/json, */*;q=0.5'")
        data_str = json.dumps(json_data, separators=(',', ':'))
        args.append(f"{'--data' if long_mode else '-d'} '{data_str}'")
    elif form_data:
        for k, v in form_data:
            args.append(f"--data-urlencode '{k}={v}'")
    elif multipart_data:
        for k, v in multipart_data:
            args.append(f"{'--form' if long_mode else '-F'} '{k}={v['filename']}'")

    print(f"{env_prefix}{curl_bin} " + " ".join(args))


def print_offline_request(method, path, query, header_list, body_bytes, opts):
    full_path = path + ("?" + query if query else "")
    lines = [f"{method} {full_path} HTTP/1.1"]

    for k, v in header_list:
        lines.append(f"{k}: {v}")

    p = opts["print"]
    if p is None:
        p = "HB"

    out = ""
    if "H" in p:
