def generate_output(kind, bin_name):
    comp_map = {
        "complete-bash": ("completions/xh.bash", f"_{bin_name}()", f'cmd="{bin_name}"'),
        "complete-elvish": ("completions/xh.elv", None, None),
        "complete-fish": ("completions/xh.fish", None, None),
        "complete-nushell": ("completions/xh.nu", None, None),
        "complete-powershell": ("completions/_xh.ps1", None, None),
        "complete-zsh": ("completions/_xh", None, None),
        "man": ("doc/man-template.roff", None, None)
    }
    if kind in comp_map:
        filepath, _, _ = comp_map[kind]
        if os.path.exists(filepath):
            with open(filepath, "r", encoding="utf-8") as f:
                content = f.read()
            if kind == "man":
                content = content.replace("{{date}}", "2026-07-31").replace("{{version}}", VERSION)
            elif kind == "complete-bash":
                content = content.replace("_xh()", f"_{bin_name}()").replace('cmd="xh"', f'cmd="{bin_name}"')
            elif kind == "complete-zsh":
                content = content.replace("#compdef xh", f"#compdef {bin_name}")
            sys.stdout.write(content)
            return
    print(f"Unknown generation kind: {kind}", file=sys.stderr)


if __name__ == "__main__":
    main()
